'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { supabase } from '@/lib/supabase/client';
import { useAuth } from '@/lib/auth';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Loader2, AlertCircle } from 'lucide-react';
import { toast } from 'sonner';

const BRAND = '#C81E1E';
const LOGO_SRC =
  'data:image/png;base64,';

export default function LoginPage() {
  const router = useRouter();
  const { session } = useAuth();
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  if (session) {
    router.replace('/dashboard');
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      if (mode === 'signup') {
        const { error } = await supabase.auth.signUp({
          email,
          password,
          options: { data: { full_name: fullName } },
        });
        if (error) throw error;
        toast.success('Cuenta creada. Ahora puedes iniciar sesión.');
        setMode('login');
        setPassword('');
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (error) throw error;
        router.replace('/dashboard');
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Error desconocido';
      setError(msg === 'Invalid login credentials'
        ? 'Credenciales inválidas. Verifica tu correo y contraseña.'
        : msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen w-full bg-white">
      {/* IZQUIERDA: formulario */}
      <div className="flex w-full flex-col justify-center px-6 py-12 sm:px-12 lg:w-[560px] lg:flex-shrink-0 lg:px-20">
        <div className="mx-auto w-full max-w-md animate-fade-in">
          <div className="mb-8 flex flex-col items-center gap-3">
            <img
              src={LOGO_SRC}
              alt="Batalla de Junín S.A.C."
              className="h-14 w-auto object-contain"
            />
            <div className="text-center">
              <h1 className="text-2xl font-bold tracking-tight text-[#1A1A1A]">
                Bienvenido a la Plataforma SSOMA
              </h1>
              <p className="mt-1 text-sm text-muted-foreground">
                Seguridad, Salud Ocupacional y Medio Ambiente
              </p>
            </div>
          </div>

          <Card className="border-border/60 shadow-xl">
            <CardHeader>
              <CardTitle className="text-xl">
                {mode === 'login' ? 'Iniciar sesión' : 'Crear cuenta'}
              </CardTitle>
              <CardDescription>
                {mode === 'login'
                  ? 'Accede al panel de gestión de seguridad'
                  : 'Regístrate para empezar a usar la plataforma'}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                {mode === 'signup' && (
                  <div className="space-y-2">
                    <Label htmlFor="name">Nombre completo</Label>
                    <Input
                      id="name"
                      type="text"
                      placeholder="Juan Pérez"
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      required
                    />
                  </div>
                )}
                <div className="space-y-2">
                  <Label htmlFor="email">Correo electrónico</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="juan@empresa.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="password">Contraseña</Label>
                  <Input
                    id="password"
                    type="password"
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    minLength={6}
                  />
                </div>

                {error && (
                  <div className="flex items-center gap-2 rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">
                    <AlertCircle className="h-4 w-4 shrink-0" />
                    {error}
                  </div>
                )}

                <Button
                  type="submit"
                  className="w-full bg-[#C81E1E] text-white hover:bg-[#A81717]"
                  disabled={loading}
                >
                  {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  {mode === 'login' ? 'Entrar' : 'Registrarse'}
                </Button>
              </form>

              <div className="mt-4 text-center text-sm text-muted-foreground">
                {mode === 'login' ? (
                  <>
                    ¿No tienes cuenta?{' '}
                    <button
                      onClick={() => {
                        setMode('signup');
                        setError('');
                      }}
                      className="font-medium text-[#C81E1E] hover:underline"
                    >
                      Regístrate
                    </button>
                  </>
                ) : (
                  <>
                    ¿Ya tienes cuenta?{' '}
                    <button
                      onClick={() => {
                        setMode('login');
                        setError('');
                      }}
                      className="font-medium text-[#C81E1E] hover:underline"
                    >
                      Inicia sesión
                    </button>
                  </>
                )}
              </div>
            </CardContent>
          </Card>

          <p className="mt-8 text-center text-xs leading-relaxed text-muted-foreground">
            SSOMA · Batalla de Junín S.A.C.
            <br />
            Ingeniería y Construcción de Obras Civiles
          </p>
        </div>
      </div>

      {/* DERECHA: panel de marca + Batallita (oculto en móvil) */}
      <div className="relative hidden flex-1 flex-col items-center justify-center overflow-hidden bg-[#C81E1E] lg:flex">
        <div className="pointer-events-none absolute -left-16 -top-16 h-52 w-52 rotate-45 rounded-3xl border-[3px] border-white/15" />
        <div className="pointer-events-none absolute bottom-10 right-14 h-32 w-32 rotate-45 rounded-2xl border-[3px] border-white/15" />
        <div className="pointer-events-none absolute -bottom-8 left-20 h-20 w-20 rotate-45 rounded-xl border-[3px] border-white/10" />

        <div className="mb-7 inline-flex items-center gap-2 rounded-full border border-white/40 px-4 py-2">
          <span className="h-[7px] w-[7px] rounded-full bg-white" />
          <span className="text-xs font-bold tracking-[0.15em] text-white">
            ÁREA SSOMA
          </span>
        </div>

        <BatallitaMascot />

        <h2 className="mt-6 text-center text-[27px] font-extrabold text-white">
          ¡Hola! Soy Batallita
        </h2>
        <p className="mt-2 max-w-[360px] text-center text-[15px] leading-relaxed text-white/85">
          Soy un oso andino (oso de anteojos), especie en peligro de
          extinción, y te acompaño a cuidar la seguridad, salud y medio
          ambiente en cada obra.
        </p>
      </div>
    </div>
  );
}

